16	/**
17	 * Sets the epoch range to check for claims.
18	 *
19	 * @param currentTimestamp - The current timestamp
20	 * @param chainId - The chain ID
21	 * @param now - The current time in milliseconds (optional, defaults to Date.now())
22	 * @param fetchBridgeConfig - The function to fetch the bridge configuration (optional, defaults to getBridgeConfig)
23	 *
24	 * @returns The epoch range to check for claims
25	 */
